&lt;p&gt;&lt;a href=&quot;https://ollama.com/settings/keys&quot;&gt;Ollama Settings — Gestion des clés SSH&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.ollama.com/&quot;&gt;Documentation officielle Ollama&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://hub.docker.com/r/ollama/ollama&quot;&gt;Image Docker Ollama sur Docker Hub&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://opencode.ai/docs/providers/#ollama&quot;&gt;OpenCode — Configuration Provider Ollama&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
