&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_实际使用案例&quot;&gt;实际使用案例&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_结论&quot;&gt;结论&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_更进一步&quot;&gt;更进一步&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_介绍&quot;&gt;介绍&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;目标受众 :&lt;/em&gt; 中级至高级 Kotlin 开发者。&lt;/div&gt;
&lt;p&gt;在Kotlin的函数式编程世界中，Arrow库提供了强大的工具来处理错误和替代情况。在这些工具中，单子`Either`以其能够表示两种可能状态的能力而脱颖而出：成功（Right）或失败（Left）。但是如何在这两种状态之间高效导航？这就是我们将在本文中探讨的内容。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_either_单子是什么&quot;&gt;Either 单子是什么？&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;单子`Either`是一种表示两种互斥可能性的数据结构。在 Kotlin 中使用 Arrow 时，它通常用于处理操作的成功和失败情况，提供了一种优雅的替代传统异常的方案。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_为什么使用_either&quot;&gt;为什么使用 Either？&lt;/h3&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;显式错误处理：迫使开发者考虑失败情况。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;函数式组合：便于链式操作，这些操作可能会失败。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Type-safety : 错误是有类型的，这有助于更精确地处理它们。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;没有例外：避免副作用和执行流的意外中断。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_上下文&quot;&gt;上下文&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;想象一下，你正在开发一个REST APIhttps://spring.io/projects/spring-boot/[Spring Boot,windows=稍后读取] et &lt;a href=&quot;https://kotlinlang.org/&quot;&gt;Kotlin&lt;/a&gt;, 使用该库https://arrow-kt.io/[箭头,窗口=稍后阅读]. 您有一个功能`findOneUserByEmail`返回一个`Either&amp;lt;Throwable, User&amp;gt;`. 您如何能以优雅且功能性的方式处理此结果？&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们有一个 User 类：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;@file:Suppress(
    &quot;RemoveRedundantQualifierName&quot;,
    &quot;MemberVisibilityCanBePrivate&quot;,
    &quot;SqlNoDataSourceInspection&quot;
)

package webapp.users

import arrow.core.Either
import arrow.core.left
import arrow.core.right
import com.fasterxml.jackson.annotation.JsonIgnore
import com.fasterxml.jackson.databind.ObjectMapper
import jakarta.validation.constraints.NotNull
import jakarta.validation.constraints.Pattern
import jakarta.validation.constraints.Size
import org.springframework.beans.factory.getBean
import org.springframework.context.ApplicationContext
import org.springframework.data.r2dbc.core.R2dbcEntityTemplate
import org.springframework.r2dbc.core.DatabaseClient
import org.springframework.r2dbc.core.awaitOne
import org.springframework.r2dbc.core.awaitRowsUpdated
import webapp.core.property.ANONYMOUS_USER
import webapp.core.property.EMPTY_STRING
import webapp.core.utils.AppUtils.cleanField
import webapp.users.EntityModel.Companion.ID_MEMBER
import webapp.users.User.UserDao.Attributes.EMAIL_ATTR
import webapp.users.User.UserDao.Attributes.ID_ATTR
import webapp.users.User.UserDao.Attributes.LANG_KEY_ATTR
import webapp.users.User.UserDao.Attributes.LOGIN_ATTR
import webapp.users.User.UserDao.Attributes.PASSWORD_ATTR
import webapp.users.User.UserDao.Attributes.VERSION_ATTR
import webapp.users.User.UserDao.Constraints.LOGIN_REGEX
import webapp.users.User.UserDao.Fields.EMAIL_FIELD
import webapp.users.User.UserDao.Fields.ID_FIELD
import webapp.users.User.UserDao.Fields.LANG_KEY_FIELD
import webapp.users.User.UserDao.Fields.LOGIN_FIELD
import webapp.users.User.UserDao.Fields.PASSWORD_FIELD
import webapp.users.User.UserDao.Fields.VERSION_FIELD
import webapp.users.User.UserDao.Relations.INSERT
import webapp.users.security.Role
import webapp.users.security.Role.RoleDao
import webapp.users.security.UserRole.UserRoleDao
import java.util.*
import jakarta.validation.constraints.Email as EmailConstraint

data class User(
    override val id: UUID? = null,

    @field:NotNull
    @field:Pattern(regexp = LOGIN_REGEX)
    @field:Size(min = 1, max = 50)
    val login: String,

    @JsonIgnore
    @field:NotNull
    @field:Size(min = 60, max = 60)
    val password: String = EMPTY_STRING,

    @field:EmailConstraint
    @field:Size(min = 5, max = 254)
    val email: String = EMPTY_STRING,

    @JsonIgnore
    val roles: MutableSet&amp;lt;Role&amp;gt; = mutableSetOf(Role(ANONYMOUS_USER)),

    @field:Size(min = 2, max = 10)
    val langKey: String = EMPTY_STRING,

    @JsonIgnore
    val version: Long = -1,
) : EntityModel&amp;lt;UUID&amp;gt;() {

    companion object {
        @JvmStatic
        fun main(args: Array&amp;lt;String&amp;gt;) = println(UserDao.Relations.sqlScript)
    }

    object UserDao {
        object Constraints {
            // Regex for acceptable logins
            const val LOGIN_REGEX =
                &quot;^(?&amp;gt;[a-zA-Z0-9!$&amp;amp;*+=?^_`{|}~.-]+@[a-zA-Z0-9-]+(?:\\.[a-zA-Z0-9-]+)*)|(?&amp;gt;[_.@A-Za-z0-9-]+)$&quot;
            const val PASSWORD_MIN: Int = 4
            const val PASSWORD_MAX: Int = 16
            const val IMAGE_URL_DEFAULT = &quot;https://placehold.it/50x50&quot;
            const val PHONE_REGEX = &quot;^(\\+|00)?[1-9]\\d{0,49}\$&quot;
        }

        object Members {
            const val PASSWORD_MEMBER = &quot;password&quot;
            const val ROLES_MEMBER = &quot;roles&quot;
        }

        object Fields {
            const val ID_FIELD = &quot;`id`&quot;
            const val LOGIN_FIELD = &quot;`login`&quot;
            const val PASSWORD_FIELD = &quot;`password`&quot;
            const val EMAIL_FIELD = &quot;`email`&quot;
            const val LANG_KEY_FIELD = &quot;`lang_key`&quot;
            const val VERSION_FIELD = &quot;`version`&quot;
        }

        object Attributes {
            val ID_ATTR = ID_FIELD.cleanField()
            val LOGIN_ATTR = LOGIN_FIELD.cleanField()
            val PASSWORD_ATTR = PASSWORD_FIELD.cleanField()
            val EMAIL_ATTR = EMAIL_FIELD.cleanField()
            const val LANG_KEY_ATTR = &quot;langKey&quot;
            val VERSION_ATTR = VERSION_FIELD.cleanField()
        }

        object Relations {
            const val TABLE_NAME = &quot;`user`&quot;
            const val SQL_SCRIPT = &quot;&quot;&quot;
            CREATE TABLE IF NOT EXISTS $TABLE_NAME (
                $ID_FIELD                     UUID default random_uuid() PRIMARY KEY,
                $LOGIN_FIELD                  VARCHAR,
                $PASSWORD_FIELD               VARCHAR,
                $EMAIL_FIELD                  VARCHAR,
                $LANG_KEY_FIELD               VARCHAR,
                $VERSION_FIELD                bigint
            );
            CREATE UNIQUE INDEX IF NOT EXISTS `uniq_idx_user_login`
            ON $TABLE_NAME ($LOGIN_FIELD);
            CREATE UNIQUE INDEX IF NOT EXISTS `uniq_idx_user_email`
            ON $TABLE_NAME ($EMAIL_FIELD);
&quot;&quot;&quot;

            @Suppress(&quot;SqlDialectInspection&quot;)
            const val INSERT = &quot;&quot;&quot;
            insert into $TABLE_NAME (
                $LOGIN_FIELD, $EMAIL_FIELD,
                $PASSWORD_FIELD, $LANG_KEY_FIELD,
                $VERSION_FIELD
            ) values ( :login, :email, :password, :langKey, :version)&quot;&quot;&quot;

            @JvmStatic
            val sqlScript: String
                get() = setOf(
                    UserDao.Relations.SQL_SCRIPT,
                    RoleDao.Relations.SQL_SCRIPT,
                    UserRoleDao.Relations.SQL_SCRIPT
                ).joinToString(&quot;&quot;)
                    .trimMargin()
        }

        object Dao {
            val Pair&amp;lt;User, ApplicationContext&amp;gt;.toJson: String
                get() = second.getBean&amp;lt;ObjectMapper&amp;gt;().writeValueAsString(first)

            suspend fun Pair&amp;lt;User, ApplicationContext&amp;gt;.save(): Either&amp;lt;Throwable, Long&amp;gt; = try {
                second.getBean&amp;lt;R2dbcEntityTemplate&amp;gt;()
                    .databaseClient
                    .sql(INSERT)
                    .bind(LOGIN_ATTR, first.login)
                    .bind(EMAIL_ATTR, first.email)
                    .bind(PASSWORD_ATTR, first.password)
                    .bind(LANG_KEY_ATTR, first.langKey)
                    .bind(VERSION_ATTR, first.version)
                    .fetch()
                    .awaitRowsUpdated()
                    .right()
            } catch (e: Throwable) {
                e.left()
            }


            suspend fun ApplicationContext.findOneUserByEmail(
                email: String
            ): Either&amp;lt;Throwable, User&amp;gt; = try {
                getBean&amp;lt;DatabaseClient&amp;gt;()
                    .sql(&quot;SELECT * FROM `user` WHERE LOWER(email) = LOWER(:email)&quot;)
                    .bind(&quot;email&quot;, email)
                    .fetch()
                    .awaitOne()
                    .let { row -&amp;gt;
                        User(
                            id = row[ID_ATTR] as UUID?,
                            login = row[LOGIN_ATTR] as String,
                            password = row[PASSWORD_ATTR] as String,
                            email = row[EMAIL_ATTR] as String,
                            langKey = row[LANG_KEY_ATTR] as String,
                            version = row[VERSION_ATTR] as Long
                        )
                    }.right()
            } catch (e: Throwable) {
                e.left()
            }
        }
    }

    /** Account REST API URIs */
    object UserRestApis {
        const val API_AUTHORITY = &quot;/api/authorities&quot;
        const val API_USERS = &quot;/api/users&quot;
        const val API_SIGNUP = &quot;/signup&quot;
        const val API_SIGNUP_PATH = &quot;$API_USERS$API_SIGNUP&quot;
        const val API_ACTIVATE = &quot;/activate&quot;
        const val API_ACTIVATE_PATH = &quot;$API_USERS$API_ACTIVATE?key=&quot;
        const val API_ACTIVATE_PARAM = &quot;{activationKey}&quot;
        const val API_ACTIVATE_KEY = &quot;key&quot;
        const val API_RESET_INIT = &quot;/reset-password/init&quot;
        const val API_RESET_FINISH = &quot;/reset-password/finish&quot;
        const val API_CHANGE = &quot;/change-password&quot;
        const val API_CHANGE_PATH = &quot;$API_USERS$API_CHANGE&quot;
    }
}

// Abstract entity model with Generic ID, which can be of any type
abstract class EntityModel&amp;lt;T&amp;gt;(
    open val id: T? = null
) {
    companion object {
        const val ID_MEMBER = &quot;id&quot;
    }
}

// Generic extension function that allows the ID to be applied to any EntityModel type
inline fun &amp;lt;reified T : EntityModel&amp;lt;ID&amp;gt;, ID&amp;gt; T.withId(id: ID): T {
    // Use reflection to create a copy with the passed ID
    return this::class.constructors.first { it.parameters.any { param -&amp;gt; param.name == ID_MEMBER } }
        .call(id, *this::class.constructors.first().parameters.drop(1).map { param -&amp;gt;
            this::class.members.first { member -&amp;gt; member.name == param.name }.call(this)
        }.toTypedArray())
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_不同的方法&quot;&gt;不同的方法&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_经典方法与_when&quot;&gt;经典方法与 `when&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val user: User by lazy { userFactory(USER) }

val result: Either&amp;lt;Throwable, User&amp;gt; = context.findOneUserByEmail(user.email)

when (result) {
    is Either.Left -&amp;gt; {
        val error = result.value
        println(&quot;Erreur : ${error.message}&quot;)
    }
    is Either.Right -&amp;gt; {
        val user = result.value
        println(&quot;Utilisateur trouvé : ${user.login}&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;虽然简单易读，但它没有充分利用Arrow的函数式能力。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_使用_fold_以获得更简洁的方法&quot;&gt;使用 &lt;code&gt;fold&lt;/code&gt; 以获得更简洁的方法&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;result.fold(
{ error -&amp;gt; println(&quot;Erreur : ${error.message}&quot;) },
{ user -&amp;gt; println(&quot;Utilisateur trouvé : ${user.login}&quot;) }
)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`fold`可以为 Left 和 Right 两种情况定义操作，简洁且优雅。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_使用_map_和_mapleft_进行转换&quot;&gt;使用 &lt;code&gt;map&lt;/code&gt; 和 &lt;code&gt;mapLeft&lt;/code&gt; 进行转换&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val processedResult = result
    .map { user -&amp;gt; &quot;Utilisateur trouvé : ${user.login}&quot; }
    .mapLeft { error -&amp;gt; &quot;Erreur : ${error.message}&quot; }

println(processedResult.merge())&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这种方法可以在保持 Either 结构不变的情况下转换其中的值，适用于更复杂的处理链。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_使用_getorelse_的错误处理&quot;&gt;使用 &lt;code&gt;getOrElse&lt;/code&gt; 的错误处理&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val user = result.getOrElse { error -&amp;gt;
    println(&quot;Erreur : ${error.message}&quot;)
    User(login = &quot;default&quot;, email = &quot;default@example.com&quot;) // utilisateur par défaut
}
println(&quot;Login : ${user.login}&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`getOrElse`它提供了一种优雅的错误处理方式，通过允许提供默认值。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_使用_onleft_和_onright_的侧向动作&quot;&gt;使用 &lt;code&gt;onLeft&lt;/code&gt; 和 &lt;code&gt;onRight&lt;/code&gt; 的侧向动作&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;result.onLeft { error -&amp;gt; println(&quot;Erreur : ${error.message}&quot;) }
.onRight { user -&amp;gt; println(&quot;Utilisateur trouvé : ${user.login}&quot;) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这些方法可以在每一边执行操作而不修改 Either，非常适合用于日志记录或轻微的副作用。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_使用_flatmap_进行操作链&quot;&gt;使用 &lt;code&gt;flatMap&lt;/code&gt; 进行操作链&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;fun findUser(email: String): Either&amp;lt;Throwable, User&amp;gt; = // ... implémentation

fun getUserPermissions(user: User): Either&amp;lt;Throwable, List&amp;lt;String&amp;gt;&amp;gt; = // ... implémentation

val userPermissions = findUser(&quot;user@example.com&quot;)
    .flatMap { user -&amp;gt; getUserPermissions(user) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;flatMap`有助于将那些自身返回的操作链接起来`Either&lt;/code&gt;，从而避免了`Either`嵌套的&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_双向转换使用_bimap&quot;&gt;双向转换使用 `bimap&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val result: Either&amp;lt;Throwable, User&amp;gt; = // ... obtention du résultat
val processedResult = result.bimap(
    { error -&amp;gt; &quot;Erreur: ${error.message}&quot; },
    { user -&amp;gt; &quot;Utilisateur: ${user.login}&quot; }
)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`bimap`可以在一次操作中同时转换左侧和右侧。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_使用_swap_进行侧面反转&quot;&gt;使用 &lt;code&gt;swap&lt;/code&gt; 进行侧面反转&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val result: Either&amp;lt;Throwable, User&amp;gt; = // ... obtention du résultat
val swapped = result.swap()&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;swap`在您想要反转某物的两侧时很有用`Either&lt;/code&gt;, 例如，用于将一个函数的接口适配到另一个函数。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_使用_tap_和_tapleft&quot;&gt;使用 &lt;code&gt;tap&lt;/code&gt; 和 &lt;code&gt;tapLeft&lt;/code&gt; :&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;result.tap { user -&amp;gt; println(&quot;Utilisateur trouvé : ${user.login}&quot;) }
.tapLeft { error -&amp;gt; println(&quot;Erreur : ${error.message}&quot;) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;类似于`onLeft` et &lt;code&gt;onRight&lt;/code&gt;, 但是这些方法返回原始的 Either，这对于链式操作很有用。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_使用_recover&quot;&gt;使用 &lt;code&gt;recover&lt;/code&gt; :&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val recoveredUser = result.recover { error -&amp;gt;
    println(&quot;Erreur récupérée : ${error.message}&quot;)
    User(login = &quot;recovered&quot;, email = &quot;recovered@example.com&quot;)
}
println(&quot;Login : ${recoveredUser.login}&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此方法通过提供一个替换值将 Either.Left 转换为 Either.Right。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_实际使用案例&quot;&gt;实际使用案例&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;使用`fold`适用于需要逐案处理的简单操作。 - 更倾向于`map` et &lt;code&gt;mapLeft`用于数据转换而不更改结构的`Either&lt;/code&gt;. - 选择`flatMap`在可能失败的操作链中。 - 使用`recover`为提供默认值以防出错。 - 选择`onLeft` et &lt;code&gt;onRight&lt;/code&gt; (ou &lt;code&gt;tap&lt;/code&gt; et &lt;code&gt;tapLeft&lt;/code&gt;) 用于诸如日志记录之类的副作用。 - 使用`bimap`将两边转换为单一操作。 - 应用`swap`当您需要将一个函数的接口适配到另一个函数时。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_结论&quot;&gt;结论&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;每种方法根据使用情境各有其优势。诸如这些方法`fold`, &lt;code&gt;map&lt;/code&gt;(Empty)&lt;code&gt;mapLeft&lt;/code&gt;, et `recover`在您希望链式执行多个操作或以函数式方式转换数据时特别有用。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;单子`Either`Arrow 提供了出色的灵活性，用于在 Kotlin 应用程序中处理成功和错误情况。通过掌握这些不同的方法，您将能够编写更健壮、更易读且更具功能性的代码。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在您的下一个项目中，不要犹豫去探索这些技术，以充分利用 Kotlin 和 Arrow 的函数式编程！&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_更进一步&quot;&gt;更进一步&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arrow 的官方文档：https://arrow-kt.io/docs/apidocs/arrow-core/arrow.core/-either/[箭头 任一] - Kotlin 协程与 Arrow :https://arrow-kt.io/docs/fx/[Arrow Fx 协程]&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;别忘记分享你的经验和你最喜欢的工作技巧`Either`在下面的评论中！&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_介绍&quot;&gt;介绍&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_使用命令_find&quot;&gt;使用命令 `find&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_find_的附加选项&quot;&gt;find` 的附加选项&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_使用命令_locate&quot;&gt;使用命令 `locate&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_使用命令_grep_在文件中搜索文本&quot;&gt;使用命令 &lt;code&gt;grep&lt;/code&gt; 在文件中搜索文本&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_结论&quot;&gt;结论&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_介绍&quot;&gt;介绍&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;问题： 在 Linux 操作系统的终端中搜索文件。&lt;/div&gt;
&lt;p&gt;在本文中，我们将探讨如何在 Ubuntu 中使用 Zsh 终端搜索文件。Zsh（Z shell）是一种功能强大且广泛使用的命令解释器，因其灵活性和高级功能而受到欢迎。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ubuntu，一种流行的 Linux 发行版，提供了多种命令行工具来搜索文件。我们将看到如何使用诸如`find`, &lt;code&gt;locate&lt;/code&gt; et `grep`在终端中快速有效地定位文件。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_使用命令_find&quot;&gt;使用命令 `find&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;命令`find`可以在特定目录及其子目录中搜索文件。其基本语法如下：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;find [chemin] -name [nom_du_fichier]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这是一个实际示例，我们正在搜索一个名为的文件。&lt;code&gt;example.txt`在目录中&lt;/code&gt;/home`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;find /home -name &quot;example.txt&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此命令将遍历所有子目录`/home`并显示文件的完整路径（如果已找到）。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;命令的在线手册`find` : &lt;a href=&quot;https://man.archlinux.org/man/find.1.fr/&quot;&gt;man find&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_find_的附加选项&quot;&gt;find` 的附加选项&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;命令`find`非常强大，具有许多选项。以下是一些有用的例子：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;按文件类型搜索&lt;/strong&gt;: 要仅搜索文件，请使用`-type f`, 并且要搜索目录，请使用`-type d`. - &lt;strong&gt;按尺寸搜索&lt;/strong&gt;: 你也可以根据文件大小使用该选项来过滤文件`-size`. Par exemple, pour rechercher des fichiers de plus de 100 Mo, utilisez :&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;find /home -size +100M&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_使用命令_locate&quot;&gt;使用命令 `locate&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;命令`locate`比……更快`find`因为它使用了一个预先索引的数据库，其中包含系统上存在的文件。您必须首先使用以下命令更新此数据库：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;sudo updatedb&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;然后，您可以像这样搜索文件：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;locate example.txt&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我使用https://fr.wikipedia.org/wiki/Z_Shell[zsh]与https://github.com/ohmyzsh/ohmyzsh/wiki[oh-my-zsh], 结果发现该命令`locate`无法从&amp;#8230;&amp;#8203;访问`zsh`但自从&amp;#8230;&amp;#8203;确实有可能`bash`, 为应对这一点，论点`-c`命令的`bash`允许启动一条命令`bash`从另一种类型的终端。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我正在查找以该模式结尾的文件`001.pdf`在用户目录中&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;bash -c &quot;locate ~/*001.pdf&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;命令的在线手册`locate`:https://man.archlinux.org/man/locate.1.fr/[man locate,windows=read-later]&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_使用命令_grep_在文件中搜索文本&quot;&gt;使用命令 &lt;code&gt;grep&lt;/code&gt; 在文件中搜索文本&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;如果您想在文件中搜索特定文本，您可以使用`grep`. 例如，为了在所有文件中搜索单词“Ubuntu”的出现`.txt`当前目录，使用 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;grep &quot;Ubuntu&quot; *.txt&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_结论&quot;&gt;结论&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在 Ubuntu 中通过 Zsh 终端搜索文件可以使用多种强大的工具。`find`灵活且提供了众多选项，而`locate`它允许使用预构建的数据库进行快速搜索。 最后,`grep`可以在文件中查找文本的出现。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这些命令为您提供了一套完整的工具，使您的文件搜索更高效并适应您的需求而每个这些命令都有一个可通过该命令查看的手册`man`&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_键盘&quot;&gt;键盘：&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ctrl键&quot;&gt;&lt;em&gt;Ctrl键&lt;/em&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_许可授权&quot;&gt;许可(授权)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_文件搜索&quot;&gt;文件搜索&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_键盘&quot;&gt;键盘：&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ctrl键&quot;&gt;&lt;em&gt;Ctrl键&lt;/em&gt;&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://korben.info/les-raccourcis-clavier-pour-bash-terminal-linux-et-macos.html&quot;&gt;链接&lt;/a&gt;&lt;br&gt;
&lt;a href=&quot;https://blogmotion.fr/systeme/astuces-bash-linux-16175&quot;&gt;其他链接&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_许可授权&quot;&gt;许可(授权)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;CHMOD 用于更改文件的权限。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;权限      命令&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U   G   W rwx rwx rwx     chmod 777 filename rwx rwx r-x     chmod 775 文件名 rwx r-x r-x     chmod 755 filename rw- rw- r--     chmod 664 filename rw- r-- r--     chmod 644 文件名&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U = 用户 G = Group W = 世界&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;r = 可读 w = 可写 x = 可执行的 - = 无权限&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;另一种查看权限的方式：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;400     由所有者读取 040     组可读 004     由任何人阅读（其他） 200     write by owner 020     按组写入 002     任何人都可以写 100 由所有者执行 010     按组执行 任何人都可以执行&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;要获得组合，只需把它们相加。&lt;br&gt;
例如，为了让所有者能够读取、写入、执行，&lt;br&gt;
已读取，已执行，按组执行以及任何人都可以执行，&lt;br&gt;
您将把 400+200+100+040+010+001 相加得到 751.&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_文件搜索&quot;&gt;&lt;a href=&quot;/blog/2024/0074_seach_file_linux_post.html&quot;&gt;文件搜索&lt;/a&gt;&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;

&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;阅读时间：10秒&lt;/em&gt;&lt;/div&gt;
&lt;p&gt;问题： 如何在 Windows 主机上暴露 Ubuntu 子系统的 8820 端口？ Ubuntu 是由命令启动的`wsl --install`。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;参考 : &lt;a href=&quot;https://www.it-connect.fr/wsl-2-port-forwarding-comment-acceder-a-sa-machine-virtuelle-a-distance/&quot;&gt;wsl-2端口转发&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;阅读时间：3分钟&lt;/em&gt; Pandoc 是一个通用的文档转换器&lt;/div&gt;
&lt;p&gt;Pandoc 是一种开源的文本处理软件，可用于在不同格式之间转换文档。 有几种安装 Pandoc 的方式。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_从下载页面安装&quot;&gt;&lt;strong&gt;从下载页面安装&lt;/strong&gt;&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;要从下载页面安装 Pandoc，请按照以下步骤操作：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;�访问 Pandoc 下载页面：https://pandoc.org/installing.html/[&lt;a href=&quot;https://pandoc.org/installing.html&quot; class=&quot;bare&quot;&gt;https://pandoc.org/installing.html&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;下载您操作系统的软件包安装程序。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;运行安装程序以安装 Pandoc。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;从 zip 文件安装&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;要从 zip 文件安装 Pandoc，请按照以下步骤：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;下载包含 Pandoc 二进制文件和文档的 zip 文件。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;解压缩 zip 文件。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;将二进制文件移动到您选择的目录。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;使用 Chocolatey 安装&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;要使用 Chocolatey 安装 Pandoc，请按照以下步骤：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;打开命令提示符。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;�执行以下命令：&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-powershell&quot; data-lang=&quot;powershell&quot;&gt;choco install pandoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;使用 winget 进行安装&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;要使用 winget 安装 Pandoc，请按以下步骤操作：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;打开命令提示符。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;执行以下命令：&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-powershell&quot; data-lang=&quot;powershell&quot;&gt;winget install --source winget --exact --id JohnMacFarlane.Pandoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;建议&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;默认情况下，Pandoc 使用 LaTeX 创建 PDF。 建议通过 MiKTeX 安装 LaTeX。 带有该选项`--pdf-engine`, 您也可以为此任务指定其他程序。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;警告&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;使用多种安装方法可能导致 Pandoc 的两个独立安装。 建议在切换到替代安装方法之前正确卸载 Pandoc。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;在linux上通过WSL的安装&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;请确认您的包管理器中 pandoc 的版本不是过时的。 Pandoc 位于 Debian、Ubuntu、Slackware、Arch、Fedora、NixOS、openSUSE、gentoo 和 Void 的软件仓库中。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;要获取最新版本，我们在下载页面提供适用于 amd64 架构的二进制包。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;可执行文件是静态链接的，没有动态依赖，也没有对外部数据文件的依赖。 注意：由于静态链接，此包的 pandoc 二进制文件无法使用需要外部 C 编写的 Lua 模块的 Lua 过滤器。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;提供一个 tarball 和一个 deb 安装程序。 要安装 deb :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;sudo dpkg -i $DEB&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;写作时的例子：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;wget https://github.com/jgm/pandoc/releases/download/3.1.11.1/pandoc-3.1.11.1-1-amd64.deb&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;sudo dpkg -i pandoc-3.1.11.1-1-amd64.deb&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;où `$DEB`是下载的deb文件的路径。 这将安装可执行文件`pandoc`和手册页。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;如果您使用的是基于 RPM 的发行版，您可能能够使用 alien 从我们的下载页面安装 deb 包。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在任何发行版中，您可以从 tarball 中`$DEST`(例如，&lt;code&gt;/usr/local/&lt;/code&gt; ou &lt;code&gt;$HOME/.local&lt;/code&gt;) 通过做 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;tar xvzf $TGZ --strip-components 1 -C $DEST&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;où `$TGZ`是下载的压缩 tarball 的路径。 对于 Pandoc 2.0 之前的版本，这些版本不提供 tarball，请尝试以下方法：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;ar p $DEB data.tar.gz | tar xvz --strip-components 2 -C $DEST&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;您也可以从源代码安装，使用下面的说明下`Compilation à partir de la source`。 请注意，大多数发行版的软件包仓库中都包含 Haskell 平台。 例如，在 Debian/Ubuntu 上，您可以使用它来安装&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;apt-get install haskell-platform&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;默认情况下，Pandoc 使用 LaTeX 创建 PDF。 我们建议通过您的包管理器安装TeX Live。 (在 Debian/Ubuntu,&lt;code&gt;apt-get install texlive&lt;/code&gt;). 带有选项`--pdf-engine`不过，您也可以为此任务指定其他程序。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;阅读时间：2 分钟&lt;/em&gt; 创建 kotlin.Triple 类的完整实现，使用 JavaScript、TypeScript 和 Python，采用函数式编程。&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;注意：&lt;/strong&gt;这些类型`Maybe`, &lt;code&gt;Either&lt;/code&gt;, `Result`它们不是 JavaScript 或 TypeScript 基础语言的一部分，因此我们必须自己实现它们。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_javascript&quot;&gt;JavaScript&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;//javascript
// Maybe type
const Maybe = (value) =&amp;gt; ({
  map: (fn) =&amp;gt; (value !== null &amp;amp;&amp;amp; value !== undefined ? Maybe(fn(value)) : Maybe(null)),
  flatMap: (fn) =&amp;gt; (value !== null &amp;amp;&amp;amp; value !== undefined ? fn(value) : Maybe(null)),
  getOrElse: (defaultValue) =&amp;gt; (value !== null &amp;amp;&amp;amp; value !== undefined ? value : defaultValue),
});

// Either type
const Either = {
  Left: (value) =&amp;gt; ({
    map: (fn) =&amp;gt; Either.Left(value),
    flatMap: (fn) =&amp;gt; Either.Left(value),
    getOrElse: (defaultValue) =&amp;gt; defaultValue,
    isLeft: true,
    isRight: false,
  }),
  Right: (value) =&amp;gt; ({
    map: (fn) =&amp;gt; Either.Right(fn(value)),
    flatMap: (fn) =&amp;gt; fn(value),
    getOrElse: (defaultValue) =&amp;gt; value,
    isLeft: false,
    isRight: true,
  }),
};

// Triple class
class Triple {
  constructor(a, b, c) {
    this.a = a;
    this.b = b;
    this.c = c;
  }

  map(fn) {
    return new Triple(fn(this.a), fn(this.b), fn(this.c));
  }

  static of(a, b, c) {
    return new Triple(a, b, c);
  }

  // Example method using Maybe and Either
  divideBy(other) {
    return Maybe(this.b)
      .flatMap((numerator) =&amp;gt;
        Maybe(other)
          .flatMap((denominator) =&amp;gt;
            denominator !== 0
              ? Either.Right(numerator / denominator)
              : Either.Left(&#39;Division by zero&#39;)
          )
      )
      .getOrElse(Either.Left(&#39;Invalid input&#39;));
  }
}

// Example usage
const triple = Triple.of(1, 2, 3);
const result = triple.map((x) =&amp;gt; x * 2);
console.log(result); // Triple { a: 2, b: 4, c: 6 }

const divisionResult = triple.divideBy(2);
console.log(divisionResult); // Either.Right { value: 1 }

const invalidDivisionResult = triple.divideBy(0);
console.log(invalidDivisionResult); // Either.Left { value: &#39;Division by zero&#39; }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_typescript&quot;&gt;TypeScript&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-typescript&quot; data-lang=&quot;typescript&quot;&gt;//Typescript
// Maybe type
// noinspection JSAnnotator

type Maybe&amp;lt;T&amp;gt; = {
  map&amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; U): Maybe&amp;lt;U&amp;gt;;
  flatMap&amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; Maybe&amp;lt;U&amp;gt;): Maybe&amp;lt;U&amp;gt;;
  getOrElse(defaultValue: T): T;
};

const just = &amp;lt;T&amp;gt;(value: T): Maybe&amp;lt;T&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; U) =&amp;gt; just(fn(value)),
  flatMap: &amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; Maybe&amp;lt;U&amp;gt;) =&amp;gt; fn(value),
  getOrElse: (_: T) =&amp;gt; value,
});

const nothing = &amp;lt;T&amp;gt;(): Maybe&amp;lt;T&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(_: (value: T) =&amp;gt; U) =&amp;gt; nothing&amp;lt;U&amp;gt;(),
  flatMap: &amp;lt;U&amp;gt;(_: (value: T) =&amp;gt; Maybe&amp;lt;U&amp;gt;) =&amp;gt; nothing&amp;lt;U&amp;gt;(),
  getOrElse: (defaultValue: T) =&amp;gt; defaultValue,
});

// Either type
type Either&amp;lt;L, R&amp;gt; = {
  map&amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; U): Either&amp;lt;L, U&amp;gt;;
  flatMap&amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; Either&amp;lt;L, U&amp;gt;): Either&amp;lt;L, U&amp;gt;;
  getOrElse(defaultValue: R): R;
  isLeft: boolean;
  isRight: boolean;
};

const left = &amp;lt;L, R&amp;gt;(value: L): Either&amp;lt;L, R&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(_: (value: R) =&amp;gt; U) =&amp;gt; left&amp;lt;L, U&amp;gt;(value),
  flatMap: &amp;lt;U&amp;gt;(_: (value: R) =&amp;gt; Either&amp;lt;L, U&amp;gt;) =&amp;gt; left&amp;lt;L, U&amp;gt;(value),
  getOrElse: (defaultValue: R) =&amp;gt; defaultValue,
  isLeft: true,
  isRight: false,
});

const right = &amp;lt;L, R&amp;gt;(value: R): Either&amp;lt;L, R&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; U) =&amp;gt; right&amp;lt;L, U&amp;gt;(fn(value)),
  flatMap: &amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; Either&amp;lt;L, U&amp;gt;) =&amp;gt; fn(value),
  getOrElse: (_: R) =&amp;gt; value,
  isLeft: false,
  isRight: true,
});

// Triple class
class Triple&amp;lt;T&amp;gt; {
  constructor(public a: T, public b: T, public c: T) {}

  map&amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; U): Triple&amp;lt;U&amp;gt; {
    return new Triple&amp;lt;U&amp;gt;(fn(this.a), fn(this.b), fn(this.c));
  }

  static of&amp;lt;T&amp;gt;(a: T, b: T, c: T): Triple&amp;lt;T&amp;gt; {
    return new Triple&amp;lt;T&amp;gt;(a, b, c);
  }

  // Example method using Maybe and Either
  divideBy(other: T): Either&amp;lt;string, number&amp;gt; {
    return just(this.b)
      .flatMap((numerator) =&amp;gt;
        just(other)
          .flatMap((denominator) =&amp;gt;
            denominator !== 0 ? right(numerator / denominator) : left(&#39;Division by zero&#39;)
          )
      )
      .getOrElse(left(&#39;Invalid input&#39;));
  }
}

// Example usage
const triple = Triple.of(1, 2, 3);
const result = triple.map((x) =&amp;gt; x * 2);
console.log(result); // Triple { a: 2, b: 4, c: 6 }

const divisionResult = triple.divideBy(2);
console.log(divisionResult); // Either.Right { value: 1 }

const invalidDivisionResult = triple.divideBy(0);
console.log(invalidDivisionResult); // Either.Left { value: &#39;Division by zero&#39; }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_python_pydantic_pymonad&quot;&gt;Python, pydantic, pymonad&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;创建一个使用 Python 的实现`pydantic`用于类型验证和`pymonad`对于单子：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;安装依赖 :&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;pip install pydantic pymonad&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-python&quot; data-lang=&quot;python&quot;&gt;from pymonad.either import Either, Left, Right
from pydantic import BaseModel, ValidationError, validator

# Définition de la classe Triple avec Pydantic
class Triple(BaseModel):
    a: int
    b: int
    c: int

    @validator(&#39;b&#39;)
    def validate_b(cls, b, values):
        if b == 0:
            raise ValueError(&#39;Division by zero is not allowed&#39;)
        return b

    # Méthode utilisant Either pour la gestion des erreurs
    def divide_by(self, other):
        def division(numerator, denominator):
            return Right(numerator / denominator)

        def handle_error(error):
            return Left(str(error))

        return Either(lambda: division(self.b, other)).or_else(handle_error)

# Exemple d&#39;utilisation
try:
    triple = Triple(a=1, b=2, c=3)
    result = triple.divide_by(2)

    if result.is_right:
        print(f&#39;Division result: {result.value}&#39;)
    else:
        print(f&#39;Error: {result.value}&#39;)

except ValidationError as e:
    print(f&#39;Validation Error: {e}&#39;)
except Exception as e:
    print(f&#39;An unexpected error occurred: {e}&#39;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在此示例：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;pydantic`定义类`Triple&lt;/code&gt;� 带有类型化的字段。 - 方法`divide_by`使用单子`Either` de `pymonad`用于处理由除以零导致的潜在错误。 - 自定义验证以确保值的`b`不等于零。如果等于零，则会引发异常，并`pymonad`捕获此异常以返回一个结果`Left`指示错误。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_目录&quot;&gt;目录&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;阅读时间：30分钟&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#引言&quot;&gt;[引言]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Google Apps Script 基本结构&quot;&gt;[Google Apps Script 基本结构]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Google Apps Script 中的类型和变量&quot;&gt;[Google Apps Script 中的类型和变量]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#常量、变量和在 Google Apps Script 中的字母&quot;&gt;[常量、变量和在 Google Apps Script 中的字母]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Google Apps Script 中的操作和运算符&quot;&gt;[Google Apps Script 中的操作和运算符]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Var、Let 和 Const 在 Google Apps Script 中&quot;&gt;[Var、Let 和 Const 在 Google Apps Script 中]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Google Apps Script 中的控制结构&quot;&gt;[Google Apps Script 中的控制结构]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#_google_apps_script_中的循环&quot;&gt;Google Apps Script 中的循环&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#_google_apps_script_中的对象&quot;&gt;Google Apps Script 中的对象&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Google Apps Script 中的函数&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Google Apps Script 中的设置和作用域&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Google Apps Script 中的 Rest 和 Spread 运算符&quot;&gt;[Google Apps Script 中的 Rest 和 Spread 运算符]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#在 Google Apps Script 中通过分解进行的分配&quot;&gt;[在 Google Apps Script 中通过分解进行的分配]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#集合和声明式编程在 Google Apps Script 中&quot;&gt;[集合和声明式编程在 Google Apps Script 中]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_介绍&quot;&gt;介绍&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Google Apps Script (GAS) 是一种与 Google 的多种服务（如 Google Sheets、Google Docs 和 Google Forms）关联的脚本开发平台。它可以自动化任务、添加自定义功能以及集成 Google 服务。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在这份备忘录中，我们将通过具体示例探索 Google Apps Script 的主要概念。我们将讨论诸如变量、循环、函数等概念，并还有许多其他内容，针对 GAS 的特定情境进行调整。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script_的基本结构&quot;&gt;Google Apps Script 的基本结构&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;首先，让我们检查一下Google Apps脚本的基本结构。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Structure de base en Google Apps Script
 */
function exempleStructureGAS() {
    // Votre code ici
    Logger.log(&quot;Hello, Google Apps Script!&quot;);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_类型和变量在_google_apps_script_中&quot;&gt;类型和变量在 Google Apps Script 中&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Google Apps Script 使用 JavaScript 作为编程语言。数据类型和变量的工作方式与标准 JavaScript 类似。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Types et Variables en Google Apps Script
 */
function exempleTypesVariablesGAS() {
    // Votre code ici
    var nombre = 42;
    var texte = &quot;Bonjour, Google Apps Script!&quot;;
    Logger.log(nombre);
    Logger.log(texte);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_操作和运算符在_google_apps_script_中&quot;&gt;操作和运算符在 Google Apps Script 中&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Google Apps Script 中的操作和运算符与 JavaScript 中的相同。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Opérations et Opérateurs en Google Apps Script
 */
function exempleOperationsGAS() {
    // Votre code ici
    var x = 10;
    var y = 5;
    var resultat = x + y;
    Logger.log(resultat);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_变量let_和_const_在_google_apps_script_中&quot;&gt;变量、let 和 const 在 Google Apps Script 中&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在 GAS 中，概念的`var`, &lt;code&gt;let&lt;/code&gt;, et `const`用于声明变量。然而，理解它们之间的差异及其影响是至关重要的。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Var, Let et Const en Google Apps Script
 */
function exempleVarLetConstGAS() {
    // Votre code ici
    // Utilisation de var
    var x = 10;
    if (true) {
        var x = 20; // La variable x est modifiée globalement
    }
    Logger.log(x);

    // Utilisation de let
    let y = 30;
    if (true) {
        let y = 40; // La variable y est limitée au bloc if
    }
    Logger.log(y);

    // Utilisation de const
    const z = 50;
    // z = 60; // Impossible de réassigner une constante
    Logger.log(z);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script中的控制结构&quot;&gt;Google Apps Script中的控制结构&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;控制结构例如`if`, &lt;code&gt;else&lt;/code&gt;, &lt;code&gt;while&lt;/code&gt; et `for`用于在 Google Apps Script 中管理执行流程。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Structures de Contrôle en Google Apps Script
 */
function exempleStructuresControleGAS() {
    // Votre code ici
    var condition = true;

    if (condition) {
        Logger.log(&quot;La condition est vraie.&quot;);
    } else {
        Logger.log(&quot;La condition est fausse.&quot;);
    }

    var compteur = 0;
    while (compteur &amp;lt; 5) {
        Logger.log(compteur);
        compteur++;
    }

    for (var i = 0; i &amp;lt; 3; i++) {
        Logger.log(i);
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_参数和作用域在_google_apps_script_中&quot;&gt;参数和作用域在 Google Apps Script 中&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;参数和作用域在 GAS 脚本开发中起着至关重要的作用。了解它们的工作原理，以避免出现意外行为。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Paramètres et Scopes en Google Apps Script
 */
function exempleParametresScopesGAS(parametre) {
    // Votre code ici
    var variableGlobale = &quot;Je suis global&quot;;

    function afficherParametre() {
        Logger.log(parametre);
    }

    afficherParametre();
    Logger.log(variableGlobale);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_常量变量和字母在_google_apps_script_中&quot;&gt;常量、变量和字母在 Google Apps Script 中&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;理解&amp;#8230;&amp;#8203;之间的差别`const`, &lt;code&gt;var&lt;/code&gt;, et `let`对于在Google Apps Script中有效使用变量至关重要。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Constantes, Variables, et Lettres en Google Apps Script
 */
function exempleConstantesVariablesLettresGAS() {
    // Votre code ici
    const constante = &quot;Je ne change pas&quot;;
    Logger.log(constante);

    var variable = &quot;Je peux changer&quot;;
    Logger.log(variable);

    let lettre = &quot;Je peux aussi changer, mais seulement dans mon bloc&quot;;
    Logger.log(lettre);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script_中的循环&quot;&gt;Google Apps Script 中的循环&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;循环，例如`for` et &lt;code&gt;while&lt;/code&gt;, 是遍历元素和执行重复操作所必需的。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Boucles en Google Apps Script
 */
function exempleBouclesGAS() {
    // Votre code ici
    for (var i = 0; i &amp;lt; 3; i++) {
        Logger.log(i);
    }

    var condition = true;
    var compteur = 0;

    while (condition) {
        Logger.log(&quot;Tour de boucle&quot;);
        compteur++;
        if (compteur === 3) {
            condition = false;
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script_中的对象&quot;&gt;Google Apps Script 中的对象&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;对象用于结构化数据。在 GAS 中，许多内置对象有助于与 Google 服务进行交互。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Objets en Google Apps Script
 */
function exempleObjetsGAS() {
    // Votre code ici
    var feuille = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
    var cellule = feuille.getRange(&quot;A1&quot;);
    cellule.setValue(&quot;Nouvelle valeur&quot;);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_常量变量和字母在_google_apps_script_中_2&quot;&gt;常量、变量和字母在 Google Apps Script 中&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;理解&amp;#8230;&amp;#8203;之间的差异`const`, &lt;code&gt;var&lt;/code&gt;, et `let`这对于在 Google Apps Script 中高效使用变量是必不可少的。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Constantes, Variables, et Lettres en Google Apps Script
 */
function exempleConstantesVariablesLettresGAS() {
    // Votre code ici
    const constante = &quot;Je ne change pas&quot;;
    Logger.log(constante);

    var variable = &quot;Je peux changer&quot;;
    Logger.log(variable);

    let lettre = &quot;Je peux aussi changer, mais seulement dans mon bloc&quot;;
    Logger.log(lettre);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script_中的函数&quot;&gt;Google Apps Script 中的函数&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;函数是编程中的基本要素。在 GAS 中，它们可以以多种方式声明和调用。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Fonctions en Google Apps Script
 */
function exempleFonctionsGAS() {
    // Votre code ici
    function additionner(a, b) {
        return a + b;
    }

    var resultat = additionner(2, 3);
    Logger.log(resultat);

    // Fonction anonyme
    var multiplier = function (x, y) {
        return x * y;
    };

    Logger.log(multiplier(4, 5));
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script_中的剩余参数和展开运算符&quot;&gt;Google Apps Script 中的剩余参数和展开运算符&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;剩余运算符 (&lt;code&gt;&amp;#8230;&amp;#8203;&lt;/code&gt;) 和传播 (&lt;code&gt;&amp;#8230;&amp;#8203;&lt;/code&gt;) 对于以简洁方式操作数组和对象很有用。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Opérateurs de Repos et de Propagation en Google Apps Script
 */
function exempleOperateursReposPropagationGAS() {
    // Votre code ici
    // Opérateur de repos (...) pour les tableaux
    var nombres = [1, 2, 3, 4, 5];
    var [...copieNombres] = nombres;
    Logger.log(copieNombres);

    // Opérateur de propagation (...) pour les objets
    var objOriginal = { x: 1, y: 2 };
    var objClone = { ...objOriginal, z: 3 };
    Logger.log(objClone);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_在_google_apps_script_中的解构赋值&quot;&gt;在 Google Apps Script 中的解构赋值&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;解构赋值是一种强大的功能，允许以简洁的方式从对象和数组中提取值。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Affectation par Décomposition en Google Apps Script
 */
function exempleAffectationDecompositionGAS() {
    // Votre code ici
    var coordonnees = [3, 4];
    var [x, y] = coordonnees;
    Logger.log(x);
    Logger.log(y);

    var utilisateur = { nom: &quot;John&quot;, age: 30 };
    var { nom, age } = utilisateur;
    Logger.log(nom);
    Logger.log(age);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script_中的集合和声明式编程&quot;&gt;Google Apps Script 中的集合和声明式编程&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Google Apps Script 支持诸如数组之类的数据结构，以及函数式编程和声明式迭代 (&amp;gt;&amp;lt;命令式), 诸如`map`, &lt;code&gt;reduce&lt;/code&gt; et &lt;code&gt;forEach&lt;/code&gt;。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Collections et Programmation Déclarative en Google Apps Script
 */
function exempleCollectionsFonctionnelleGAS() {
    // Votre code ici
    // Exemple de tableau (collection)
    var nombres = [1, 2, 3, 4, 5];

    // Utilisation de forEach
    nombres.forEach(function (nombre) {
        Logger.log(nombre);
    });

    // Utilisation de map
    var carresNombres = nombres.map(function (nombre) {
        return nombre * nombre;
    });
    Logger.log(carresNombres);

    // Utilisation de reduce
    var somme = nombres.reduce(function (acc, nombre) {
        return acc + nombre;
    }, 0);
    Logger.log(somme);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_结论&quot;&gt;结论&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;本备忘录通过具体代码示例说明了Google Apps Script的基本概念。利用这些知识，您可以自动化日常任务、自定义文档，并充分发挥Google Apps Script的功能。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

